<script setup>
import { reactive } from "vue";

const { bookmark, config } = defineProps(['bookmark', 'config']);

const failedBookmarks = reactive(new Set());
const FALLBACK_EXTS = ['ico', 'svg', 'png', 'webp', 'jpg'];

function getFaviconCandidates(pageUrl) {
    try {
        const domain = new URL(pageUrl).origin;
        return FALLBACK_EXTS.map(ext => ext === 'ico' ? `${domain}/favicon.ico` : `${domain}/logo.${ext}`);
    } catch {
        return [];
    }
}

function handleFaviconError(event, bookmarkId) {
    const img = event.target;
    const candidates = JSON.parse(img.dataset.candidates);
    const nextIndex = Number(img.dataset.fallbackIndex) + 1;

    if (nextIndex < candidates.length) {
        img.dataset.fallbackIndex = nextIndex;
        img.src = candidates[nextIndex];
    } else {
        failedBookmarks.add(bookmarkId)
    }
}
</script>

<template>
    <img 
        v-if="!failedBookmarks.has(bookmark.id)"
        :src="getFaviconCandidates(bookmark.url)[0]"
        :data-candidates="JSON.stringify(getFaviconCandidates(bookmark.url))"
        data-fallback-index="0"
        @error="handleFaviconError($event, bookmark.id)"
        alt=""
        :class="{ 'w-4 h-4': config.theme.iconSize === 'small', 'w-10 h-10': config.theme.iconSize === 'medium', 'w-14 h-14': config.theme.iconSize === 'big' }"
    />
    <div v-else :class="{ 'w-4 h-4': config.theme.iconSize === 'small', 'w-10 h-10': config.theme.iconSize === 'medium', 'w-14 h-14': config.theme.iconSize === 'big' }">
